//   魔龙 —— 「省流：」「先给结论」「不建议抽」「输出手法：A-B-C」
//   萨摩 —— 「短期看是利好的，长远不好说」「应该不会额外出视频」
//   梦依 —— 突然的抒情和表白，比喻乱飞，偶尔蹦一句日语音译
//   爱丽丝 —— 数字 + 瞬爆 + 轮椅，标题党式的短句和省略号
