//   立誓 —— 教学口吻，对着「新手」说话，动不动就要出个视频
//   夏茉琳 —— 「兄弟」开头，「没激情了」结尾，速刷
//   校猫 —— 无投稿、无动态，只能靠名字和「猫」本身来写：话少、蹲着看、准

